record.field:
if not record.x_studio_user_id:
    raise UserError("Please select a Technician before assigning!")

vals = {}
if record.x_studio_selection_1 == 'Draft':
    vals['x_studio_selection_1'] = 'Confirm'

if record.x_studio_request_date and record.x_studio_warranty_end_date:
    if record.x_studio_request_date <= record.x_studio_warranty_end_date:
        vals['x_studio_warranty_status'] = 'Active'
    else:
        vals['x_studio_warranty_status'] = 'Expired'

if vals:
    record.write(vals)

template = env.ref('studio_customization.mail_template_repair_request_assigned', raise_if_not_found=False)
if not template:
    template = env['mail.template'].search([('name', '=', 'Repair Request: Assigned to Technician')], limit=1)

if template:
    template.send_mail(record.id, force_send=True)
    partner = record.x_studio_partner_id
    if partner:
        record.message_post(
            body=template._render_field('body_html', [record.id])[record.id],
            subject=template._render_field('subject', [record.id])[record.id],
            partner_ids=[partner.id],
            message_type='comment',
            subtype_xmlid='mail.mt_comment',
        )

if record.x_studio_selection_1 == 'not solved':
    if not record.x_studio_not_solved_reason or not record.x_studio_not_solved_reason.strip():
        raise UserError("Please fill in the Not Solved Reason before returning.")
    record.write({'x_studio_selection_1': 'returned'})

if not record.x_studio_invoice_id:
    raise UserError("Please create an invoice before completing the request.")
if record.x_studio_invoice_id.state != 'posted':
    raise UserError("Please confirm the invoice before marking as Done.")
record.write({'x_studio_selection_1': 'done'})

if not record.x_studio_partner_id:
    raise UserError("Please select a customer before sending mail.")

template = env.ref('studio_customization.mail_template_repair_not_solved', raise_if_not_found=False)
if not template:
    template = env['mail.template'].search([('name', '=', 'Repair Request: Not Solved')], limit=1)

if template:
    template.send_mail(record.id, force_send=True)
    partner = record.x_studio_partner_id
    if partner:
        record.message_post(
            body=template._render_field('body_html', [record.id])[record.id],
            subject=template._render_field('subject', [record.id])[record.id],
            partner_ids=[partner.id],
            message_type='comment',
            subtype_xmlid='mail.mt_comment',
        )

if not record.x_studio_partner_id:
    raise UserError("Please select a customer before sending mail.")

template = env.ref('studio_customization.mail_template_repair_completed', raise_if_not_found=False)
if not template:
    template = env['mail.template'].search([('name', '=', 'Repair Request: Completed')], limit=1)

if template:
    template.send_mail(record.id, force_send=True)
    partner = record.x_studio_partner_id
    if partner:
        record.message_post(
            body=template._render_field('body_html', [record.id])[record.id],
            subject=template._render_field('subject', [record.id])[record.id],
            partner_ids=[partner.id],
            message_type='comment',
            subtype_xmlid='mail.mt_comment',
        )

for rec in (records or [record]):
    if not rec.x_name or rec.x_name in ('/', 'New', ''):
        seq = env['ir.sequence'].next_by_code('repair.request.sequence.code')
        if seq:
            rec.write({'x_name': seq})

if record.x_studio_invoice_id:
    action = {
        'name': 'Customer Invoice',
        'type': 'ir.actions.act_window',
        'res_model': 'account.move',
        'res_id': record.x_studio_invoice_id.id,
        'view_mode': 'form',
        'views': [(False, 'form')],
        'target': 'current',
    }
else:
    # 1. Safely find Customer Partner ID
    partner_id = False
    if 'x_studio_partner_id' in record._fields and record.x_studio_partner_id:
        partner_id = record.x_studio_partner_id.id
    elif 'partner_id' in record._fields and record.partner_id:
        partner_id = record.partner_id.id
    elif 'x_studio_contact' in record._fields and record.x_studio_contact:
        partner_id = record.x_studio_contact.id

    if not partner_id:
        raise UserError("Please select a customer on this record before creating an invoice.")

    invoice_lines = []

    # Check if warranty is active
    is_under_warranty = (str(record.x_studio_warranty) == 'True') and (record.x_studio_warranty_status == 'Active')

    # 2. Add Repair Parts
    for rec in record.x_studio_one2many_1:
        if rec.x_studio_products_id:
            # Price is 0 if under active warranty, otherwise use standard list price
            unit_price = 0.0 if is_under_warranty else rec.x_studio_related_list_price_1
            product = rec.x_studio_products_id.product_variant_id or rec.x_studio_products_id

            invoice_lines.append((0, 0, {
                'product_id': product.id,
                'quantity': rec.x_studio_quantity or 1.0,
                'price_unit': unit_price,
            }))

    # 3. Add Accessories (always billed regardless of warranty)
    for rec in record.x_studio_one2many_2:
        if rec.x_studio_products:
            product = rec.x_studio_products.product_variant_id or rec.x_studio_products
            invoice_lines.append((0, 0, {
                'product_id': product.id,
                'quantity': rec.x_studio_accessories_quantity or 1.0,
                'price_unit': rec.x_studio_related_accessories_list_price,
            }))

    # 4. Create Invoice Record
    invoice = env['account.move'].create({
        'move_type': 'out_invoice',
        'partner_id': partner_id,
        'invoice_line_ids': invoice_lines,
    })
    record.write({'x_studio_invoice_id': invoice.id})

    # 5. Return Action to Display Invoice
    action = {
        'name': 'Customer Invoice',
        'type': 'ir.actions.act_window',
        'res_model': 'account.move',
        'res_id': invoice.id,
        'view_mode': 'form',
        'views': [(False, 'form')],
        'target': 'current',
    }

if record.x_studio_request_date and record.x_studio_warranty_end_date:
    if record.x_studio_request_date <= record.x_studio_warranty_end_date:
        record.write({'x_studio_warranty_status': 'Active'})
    else:
        record.write({'x_studio_warranty_status': 'Expired'})
